{
  "items": [
    {
      "name": "Real.sqrt_lt'",
      "module_name": "Mathlib.Data.Real.Sqrt",
      "kind": "theorem",
      "type": "∀ {x y : ℝ}, 0 < y → (√x < y ↔ x < y ^ 2)"
    },
    {
      "name": "Real.lt_sqrt_of_sq_lt",
      "module_name": "Mathlib.Data.Real.Sqrt",
      "kind": "theorem",
      "type": "∀ {x y : ℝ}, x ^ 2 < y → x < √y"
    },
    {
      "name": "Real.sqrt_pos_of_pos",
      "module_name": "Mathlib.Data.Real.Sqrt",
      "kind": "theorem",
      "type": "∀ {x : ℝ}, 0 < x → 0 < √x"
    },
    {
      "name": "Real.sqrt_lt",
      "module_name": "Mathlib.Data.Real.Sqrt",
      "kind": "theorem",
      "type": "∀ {x y : ℝ}, 0 ≤ x → 0 ≤ y → (√x < y ↔ x < y ^ 2)"
    },
    {
      "name": "Real.lt_sq_of_sqrt_lt",
      "module_name": "Mathlib.Data.Real.Sqrt",
      "kind": "theorem",
      "type": "∀ {x y : ℝ}, √x < y → x < y ^ 2"
    },
    {
      "name": "Real.sqrt_le_one",
      "module_name": "Mathlib.Data.Real.Sqrt",
      "kind": "theorem",
      "type": "∀ {x : ℝ}, √x ≤ 1 ↔ x ≤ 1"
    }
  ]
}
